func (a categoryHasManyProducts) Where(conds ...field.Expr) *categoryHasManyProducts {
	if len(conds) == 0 {
		return &a
	}

	exprs := make([]clause.Expression, 0, len(conds))
	for _, cond := range conds {
		exprs = append(exprs, cond.BeCond().(clause.Expression))
	}
	a.db = a.db.Clauses(clause.Where{Exprs: exprs})
	return &a
}

func (a categoryHasManyProducts) WithContext(ctx context.Context) *categoryHasManyProducts {
	a.db = a.db.WithContext(ctx)
	return &a
}

func (a categoryHasManyProducts) Session(session *gorm.Session) *categoryHasManyProducts {
	a.db = a.db.Session(session)
	return &a
}

func (a categoryHasManyProducts) Model(m *model.Category) *categoryHasManyProductsTx {
	return &categoryHasManyProductsTx{a.db.Model(m).Association(a.Name())}
}

func (a categoryHasManyProducts) Unscoped() *categoryHasManyProducts {
	a.db = a.db.Unscoped()
	return &a
}

